def max_calm_group_sum(n, a, b):
    # Create adjacency list for the bipartite graph
    adj = defaultdict(list)

    # Check pairs of students
    for i in range(n):
        for j in range(i + 1, n):
            if (a[i] & a[j]) == 0:
                adj[i].append(j)
                adj[j].append(i)

    # Union-Find data structure
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    # Union all connected components
    for i in range(n):
        for neighbor in adj[i]:
            union(i, neighbor)

    # Group students by their root
    groups = defaultdict(list)
    for i in range(n):
        groups[find(i)].append(i)

    # Calculate the maximum sum of calm groups
    max_sum = 0
    for group in groups.values():
        if len(group) >= 2:
            group_sum = sum(b[i] for i in group)
            if group_sum > max_sum:
                max_sum = group_sum

    return max_sum

