            bfs(graph, i, visited)
            component_count += 1

    # Check if all students are in the same component
    if component_count > 1:
        return 0

    # Sort students by their skill levels in descending order
    students = sorted(range(n), key=lambda x: skills[x], reverse=True)

    # Greedily select students who do not conflict with any previously selected students
    selected_students = []
    for student in students:
        if all((algorithms[student] & algorithms[s]) == 0 for s in selected_students):
            selected_students.append(student)

    # Return the sum of the skill levels of the selected students
    return sum(skills[s] for s in selected_students)

