def dfs(graph, u, visited, seen):
    stack = [u]
    while stack:
        u = stack.pop()
        if u not in seen:
            seen.add(u)
            for v in range(len(graph)):
                if graph[u][v] == 1 and v not in seen:
                    stack.append(v)
    return len(seen)

