from typing import List

def max_calm_group_sum(n: int, a: List[int], b: List[int]) -> int:
    max_sum = 0
    for i in range(1 << n):
        if bin(i).count('1') < 2:
            continue
        skills = [b[j] for j in range(n) if i & (1 << j)]
        if len(skills) == 1:
            continue
        works_together = True
        for j in range(len(skills)):
            for k in range(j + 1, len(skills)):
                if (a[j] & ~a[k]) == a[j]:
                    works_together = False
                    break
            if not works_together:
                break
        if works_together:
            max_sum = max(max_sum, sum(skills))
    return max_sum

